 private static NBTTagCompound rows(String title,int count,boolean enabled,boolean runtime){NBTTagCompound root=new NBTTagCompound();root.setString("Title",title);root.setBoolean("Enabled",enabled);NBTTagList list=new NBTTagList();for(int i=0;i<count;i++){NBTTagCompound row=new NBTTagCompound();row.setString("Label",i==0?" PULSE ":i==1?"SLIDER":"ROW "+i);row.setIntArray("RedstoneChannels",new int[]{13+i,17+i});row.setBoolean("Pulse",i==0);row.setBoolean("Slider",i==1);row.setInteger("Min",3);row.setInteger("Max",9);if(runtime){row.setInteger("Level",7);row.setIntArray("Levels",new int[]{7,5});row.setIntArray("LatchedChannels",new int[]{13+i});row.setBoolean("Active",true);row.setLong("PulseUntil",110);}list.appendTag(row);}root.setTag("Rows",list);return root;}
 private static NBTTagCompound input(int profile){NBTTagCompound tag=new NBTTagCompound();if(profile<=1)return tag;tag.setInteger("HousingTextureVersion",1);tag.setInteger("housingTexture",profile*7);tag.setString("selectedScreen",profile==4?"future_unknown_screen":ModBlocks.SCREEN_OPTIONS.get(profile%ModBlocks.SCREEN_OPTIONS.size()).bareId);tag.setString("inputPanel",TileEntityAnimatedScreenSelector.INPUT_PANELS[profile%TileEntityAnimatedScreenSelector.INPUT_PANELS.length]);tag.setString("secondaryInputPanel",TileEntityAnimatedScreenSelector.INPUT_PANELS[(profile+1)%TileEntityAnimatedScreenSelector.INPUT_PANELS.length]);tag.setBoolean("redstoneEnabled",profile%2==0);tag.setBoolean("RedstoneInverted",profile%2==1);tag.setInteger("displayMode",profile%3);tag.setInteger("animationSpeedIndex",profile%3);tag.setBoolean("framed",profile%2==0);tag.setBoolean("smallInput",true);tag.setInteger("wallPosition",profile%3);tag.setBoolean("CeilingMounted",profile%2==1);tag.setInteger("CeilingPosition",profile%3);tag.setInteger("MainTextureLayout",0);tag.setBoolean("SlabTileSides",false);tag.setInteger("SurfaceTextureLayout",profile%3);tag.setBoolean("SurfaceTileSides",true);tag.setIntArray("RedstoneChannels",new int[]{13,17});tag.setInteger("RedstoneChannel",13);tag.setInteger("ChannelLevel",6);tag.setBoolean("ChannelSignal",true);tag.setInteger("PrimarySurfaceTexture",profile==5?-4:7);tag.setInteger("SecondarySurfaceTexture",17);tag.setInteger("DisplayArtworkVersion",profile%2);tag.setBoolean("DisplaySplit",profile==3);tag.setInteger("DisplaySplitTop",7);tag.setInteger("DisplaySplitBottom",14);tag.setBoolean("FrameBare",profile%2==1);if(profile==3||profile==7){NBTTagCompound activation=new NBTTagCompound();activation.setInteger("Mode",2);activation.setIntArray("Textures",new int[]{7,17,14,-1});activation.setIntArray("Playback",new int[]{1,2,0,-1});activation.setIntArray("Speeds",new int[]{0,1,2,-1});tag.setTag("DisplayActivation",activation);}if(profile>=6){tag.setTag("RedstonePrimary",rows("PRIMARY",6,true,true));tag.setTag("RedstoneSecondary",rows("SECONDARY",2,true,true));NBTTagCompound forge=new NBTTagCompound(),all=new NBTTagCompound(),main=new NBTTagCompound();main.setIntArray("Channels",new int[]{29,31});main.setInteger("Range",64);main.setBoolean("Local",true);all.setTag("main",main);forge.setTag(com.vandorlabs.redstone.TransmissionSettings.SETTINGS,all);tag.setTag("ForgeData",forge);}if(profile==5){NBTTagCompound reader=new NBTTagCompound();ItemStack chip=new ItemStack(ModItems.DATA_CHIP,1,2);NBTTagCompound data=new NBTTagCompound();data.setString("ChipType","journal");data.setString("JournalTitle","One private chip owner");NBTTagList pages=new NBTTagList();pages.appendTag(new NBTTagString("Retained after copied display settings."));data.setTag("JournalPages",pages);data.setString("PhysicalChipSecret","private:screen");chip.setTagCompound(data);reader.setTag("InsertedToken",chip.writeToNBT(new NBTTagCompound()));reader.setBoolean("ChipSlot",true);reader.setInteger("TokenInsertionSequence",11);tag.setTag("ScreenChipReader",reader);tag.setInteger("ChipDisplayPage",7);}return tag;}
 private static TileEntityAnimatedScreenSelector install(NonRenderingChecks.MemoryWorld world,BlockAnimatedScreenSelector block,int meta,BlockPos pos,NBTTagCompound raw,boolean fresh){world.setBlockState(pos,block.getStateFromMeta(meta),2);TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)world.getTileEntity(pos);if(!fresh){NBTTagCompound tag=raw.copy();tag.setInteger("x",pos.getX());tag.setInteger("y",pos.getY());tag.setInteger("z",pos.getZ());tile.readFromNBT(tag);}return tile;}
 private static JsonObject apply(NonRenderingChecks.MemoryWorld world,BlockAnimatedScreenSelector block,int meta,NBTTagCompound initial,NBTTagCompound values){TileEntityAnimatedScreenSelector owner=install(world,block,meta,TARGET,initial,false);Object state=world.getBlockState(TARGET);String clipboard=values.toString();JsonObject row=new JsonObject();row.addProperty("block",block.getRegistryName().getResourcePath());row.addProperty("meta",meta);row.addProperty("target",initial.toString());row.addProperty("values",clipboard);row.addProperty("before",ProgrammableSettings.capture(world,TARGET).toString());NBTTagCompound before=owner.writeToNBT(new NBTTagCompound());int page=owner.chipPage;row.addProperty("ownedBefore",before.getCompoundTag("ScreenChipReader").toString());row.addProperty("pageBefore",page);row.addProperty("applied",ProgrammableSettings.apply(world,TARGET,values));row.addProperty("after",ProgrammableSettings.capture(world,TARGET).toString());NBTTagCompound saved=owner.writeToNBT(new NBTTagCompound());row.addProperty("saved",saved.toString());row.addProperty("ownedAfter",saved.getCompoundTag("ScreenChipReader").toString());row.addProperty("pageAfter",owner.chipPage);if(!clipboard.equals(values.toString())||world.getTileEntity(TARGET)!=owner||world.getBlockState(TARGET)!=state||!before.getCompoundTag("ScreenChipReader").equals(saved.getCompoundTag("ScreenChipReader"))||page!=owner.chipPage)throw new AssertionError("Clipboard, metadata, physical chip or runtime page changed");return row;}
 private static void clear(NonRenderingChecks.MemoryWorld world,com.vandorlabs.tiles.DeferredTileLoad deferred){for(net.minecraft.tileentity.TileEntity tile:new ArrayList<>(world.tiles.values()))tile.invalidate();net.minecraftforge.event.world.WorldEvent.Unload event=new net.minecraftforge.event.world.WorldEvent.Unload(world);com.vandorlabs.redstone.RedstoneChannels.worldUnloaded(event);deferred.worldUnload(event);com.vandorlabs.tiles.WorldActionAuthorization.unload(event);world.clear();}
 private static NBTTagCompound rowEdit(int kind){NBTTagCompound outer=new NBTTagCompound(),pair=new NBTTagCompound();pair.setTag("Primary",rows(kind==4?"TITLE\u00a7BAD":" COPIED PRIMARY ",kind==2?8:2,kind!=1,false));pair.setTag("Secondary",rows("COPIED SECONDARY",2,true,false));if(kind==3)pair.getCompoundTag("Secondary").getTagList("Rows",10).getCompoundTagAt(0).setBoolean("Slider",true);if(kind==5)pair.removeTag("Secondary");if(kind==6){pair.getCompoundTag("Primary").setString("Rows","wrong");outer.setInteger("wall_texture",7);}outer.setTag("redstone_rows",pair);return outer;}
 public static void main(String[] args)throws Exception{PropulsionPlacementLegacyOracle.initialize();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new net.minecraft.util.ResourceLocation("vandorlabs","programmable_viewscreen"));net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(com.vandorlabs.tiles.TileEntityTokenSlot.class,new net.minecraft.util.ResourceLocation("vandorlabs","token_slot"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);List<BlockAnimatedScreenSelector> blocks=new ArrayList<>();for(String id:ScreenFamilyLegacyChecks.IDS)for(net.minecraft.block.Block block:ModBlocks.BLOCKS)if(block.getRegistryName().getResourcePath().equals(id)){blocks.add((BlockAnimatedScreenSelector)block);net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(block);}if(blocks.size()!=7)throw new AssertionError("Screen roles");NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;java.lang.reflect.Constructor<com.vandorlabs.tiles.DeferredTileLoad> constructor=com.vandorlabs.tiles.DeferredTileLoad.class.getDeclaredConstructor();constructor.setAccessible(true);com.vandorlabs.tiles.DeferredTileLoad deferred=constructor.newInstance();File output=new File(args[0]);output.getParentFile().mkdirs();Gson gson=new Gson();int captures=0,partials=0,rowCases=0;try(PrintWriter out=new PrintWriter(output,"UTF-8")){for(BlockAnimatedScreenSelector block:blocks)for(int meta=0;meta<16;meta++)for(int profile=0;profile<8;profile++){NBTTagCompound initial=input(profile);install(world,block,meta,SOURCE,initial,profile==0);NBTTagCompound capture=ProgrammableSettings.capture(world,SOURCE);if(capture.hasKey("ScreenChipReader")||capture.hasKey("ChipDisplayPage")||capture.toString().contains("private:screen"))throw new AssertionError("Private chip entered clipboard");JsonObject row=apply(world,block,meta^3,input(7),capture);row.addProperty("kind","capture");row.addProperty("input",initial.toString());row.addProperty("fresh",profile==0);row.addProperty("sourceMeta",meta);out.println(gson.toJson(row));clear(world,deferred);captures++;}for(BlockAnimatedScreenSelector block:blocks)for(int meta:new int[]{0,2,13})for(int profile:new int[]{2,3,5,7})for(int edit=0;edit<EDITS.length;edit++){JsonObject row=apply(world,block,meta,input(profile),JsonToNBT.getTagFromJson(EDITS[edit]));row.addProperty("kind","partial");row.addProperty("edit",edit);out.println(gson.toJson(row));clear(world,deferred);partials++;}for(BlockAnimatedScreenSelector block:blocks)for(int profile:new int[]{2,7})for(int kind=0;kind<7;kind++){JsonObject row=apply(world,block,2,input(profile),rowEdit(kind));row.addProperty("kind","rows");row.addProperty("edit",kind);out.println(gson.toJson(row));clear(world,deferred);rowCases++;}}if(captures!=896||partials!=7*3*4*EDITS.length||rowCases!=98)throw new AssertionError("Bounded Screen matrix");byte[] raw=java.nio.file.Files.readAllBytes(output.toPath());StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(raw.length!=31388880||!hash.toString().equals("47cb5d0364cfe991f3fdc9f156552fe1a271d991e8a80b30f09d5c37c086859f"))throw new AssertionError("Released Screen copier callbacks changed: "+hash);System.out.println("Actual Copifier Screen Source PASS captures="+captures+" partials="+partials+" rowCases="+rowCases+" sevenRoles/typedSetterOrder/CHIP+rows/frame+transmission/privatePhysicalChip+pageUnchanged; Vehicle excluded");}
